#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
  TOTAL_STAGES=8
  local server='https://lifespace.onepeace.cc.cd'
  local expected='c029b83353ad36df6725906a24e0fcf7871bed3cb12d351fd8b36e92c7210646'
  local wizard_dir node_path npm_path collector status_json scan_json
  local TOKEN_ARCHIVE TOKEN_INSTALL TOKEN_STATE TOKEN_SOURCE TOKEN_AGENTS
  # No wizard profile, ambient .env, or secrets are read or written.
  ENV_FILE=/dev/null
  if [[ "${1:-}" == '--help' || "${1:-}" == '--plan' ]]; then
    say 'Node >=24.22.1 <25 / macOS 或 Linux；先由总控明确设备、操作者与允许扫描的 source-home。'
  say '1. 检查 Node 和归档  2. 选择全新私有路径、明确来源与 Agent  3. 私有安装'
    say '4. 获准网页登录与设备登记  5. 核对设备码/批准/领取'
    say '6. 手动 offline 扫描  7. 确认后 online 同步  8. 对账/仅展示 timer 计划'
    say '默认只采 Codex；新增 Grok Build/Hermes Agent 必须显式授权。读取所选 source-home 的全部支持历史，D 只限定对账；不会安装 timer 或删除状态。'
    say '运行：bash token-device-onboarding.sh [--archive /absolute/package.tgz]'
    return 0
  fi
  [[ $# -eq 0 || ( $# -eq 2 && "$1" == '--archive' ) ]] || { warn '参数无效；查看 --help。'; return 1; }
  [[ -t 0 && -t 1 ]] || { warn '请由已指定设备操作者在本机交互终端运行。'; return 1; }
  command -v node >/dev/null || { warn '需要已有 Node >=24.22.1 <25；向导不自动安装运行时。'; return 1; }
  node_path=$(command -v node)
  node -e 'const m=/^24\.(\d+)\.(\d+)$/.exec(process.versions.node);if(!m||Number(m[1])<22||(Number(m[1])===22&&Number(m[2])<1))process.exit(1)' || { warn '需要 Node >=24.22.1 <25；仅支持已经验证的稳定基线。'; return 1; }
  node_path=$(node -p 'process.execPath')
  npm_path="$(dirname "$node_path")/npm"
  [[ -x "$npm_path" ]] || { warn '所选 Node 同目录需要 npm。'; return 1; }
  export PATH="$(dirname "$node_path"):$PATH"
  node -e 'if (!["linux","darwin"].includes(process.platform)) process.exit(1)' || { warn '只支持 macOS/Linux。'; return 1; }
  wizard_dir=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)
  TOKEN_ARCHIVE="${2:-$wizard_dir/lifespace-token-collector-0.1.5.tgz}"
  banner 'LifeSpace 正式设备接入（需已指定实际设备/来源）'

  stage '检查最终原包'
  node --input-type=module - "$TOKEN_ARCHIVE" "$expected" <<'JS'
import { readFile, lstat } from 'node:fs/promises'
import { isAbsolute } from 'node:path'
import { createHash } from 'node:crypto'
try {
  const [archive, expected] = process.argv.slice(2)
  if (!isAbsolute(archive)) throw 0
  const stat = await lstat(archive)
  if (!stat.isFile() || stat.isSymbolicLink() || stat.size !== 26433) throw 0
  const bytes = await readFile(archive)
  if (bytes.length !== 26433 || createHash('sha256').update(bytes).digest('hex') !== expected) throw 0
  console.log('  包校验通过：26,433 字节 / c029b833… / Node ' + process.versions.node + ' / ' + process.platform + '/' + process.arch)
} catch { console.error('ARCHIVE_UNCONFIRMED'); process.exitCode = 1 }
JS
  say '私有本地包，未发布 npm；安装需要联网取得固定依赖，不使用 --omit=optional。'
  pause '核对本设备就是总控安排的目标，按 Enter 继续。'

  stage '明确来源和私有独立目录'
  ask TOKEN_SOURCE '允许读取的绝对 source-home（包含所选 Agent 数据目录的 home）：'
  ask TOKEN_AGENTS '显式授权的 Agent（codex、grok、hermes；逗号分隔，默认 codex）：'
  TOKEN_AGENTS="${TOKEN_AGENTS:-codex}"
  ask TOKEN_INSTALL '全新私有安装目录（绝对路径，末级须不存在）：'
  ask TOKEN_STATE '全新私有状态目录（绝对路径，末级须不存在）：'
  node --input-type=module - "$TOKEN_SOURCE" "$TOKEN_INSTALL" "$TOKEN_STATE" "$TOKEN_AGENTS" <<'JS'
import { lstat } from 'node:fs/promises'
import { isAbsolute, resolve, dirname } from 'node:path'
try {
  const [source, install, state, agentsText] = process.argv.slice(2)
  const agents = agentsText.split(',').map(value => value.trim())
  if (!agents.length || agents.some(agent => !['codex', 'grok', 'hermes'].includes(agent))
    || new Set(agents).size !== agents.length) throw 0
  for (const path of [source, install, state]) {
    if (!path || path === '/' || !isAbsolute(path) || resolve(path) !== path || /[\0\r\n]/.test(path)) throw 0
    for (let current = path; ; current = dirname(current)) {
      try { if ((await lstat(current)).isSymbolicLink()) throw 0 }
      catch (error) { if (error?.code !== 'ENOENT') throw error }
      if (dirname(current) === current) break
    }
  }
  if (!(await lstat(source)).isDirectory()) throw 0
  if (source === install || source === state || install === state || install.startsWith(state + '/') || state.startsWith(install + '/')) throw 0
  for (const path of [install, state]) {
    try { await lstat(path); throw 0 } catch (error) { if (error?.code !== 'ENOENT') throw error }
    if (!(await lstat(dirname(path))).isDirectory()) throw 0
  }
} catch { console.error('EXPLICIT_NEW_PRIVATE_PATHS_REQUIRED'); process.exitCode = 1 }
JS
  say "生产目标：$server"
  say "本机只读来源：$TOKEN_SOURCE"
  say "显式授权 Agent：$TOKEN_AGENTS（默认仅 Codex；升级/重复运行不会自动扩大）"
  say "独立安装：$TOKEN_INSTALL"
  say "独立状态：$TOKEN_STATE"
  warn '该来源下所选 Agent 的全部支持历史会被扫描并在在线同步时上传汇总，不能只上传对账日期 D。'
  confirm '这些路径、Agent 来源和全部历史已由本设备操作者明确选择？' || return 1

  stage '安装到独立私有目录'
  umask 077
  mkdir -m 700 -- "$TOKEN_INSTALL"
  "$npm_path" install --prefix "$TOKEN_INSTALL" --ignore-scripts --no-audit --no-fund --save-exact "$TOKEN_ARCHIVE"
  collector="$TOKEN_INSTALL/node_modules/.bin/lifespace-usage"
  "$collector" --version
  say '安装完成；未登记设备、未扫描来源、未创建系统任务。'
  pause '按 Enter 进入正常网页登录。'

  stage '获准网页登录与本机登记'
  open_url "$server/token"
  say '在浏览器正常登录已有获准账户，确认能进入 Token 看板。'
  say '若出现账户未获准，请停在这里并告知总控；不要修改白名单或复制登录凭据。'
  confirm '网页已获准，且允许为本设备创建登记申请？' || return 1
  "$collector" init --server "$server" --source-home "$TOKEN_SOURCE" --agents "$TOKEN_AGENTS" --state-dir "$TOKEN_STATE"
  say '上方 code 是8位设备码；记录于本机，不把状态库或领取凭据发到聊天。'
  pause '记住设备码，按 Enter 打开确认页。'

  stage '核对设备码、批准、领取'
  open_url "$server/token/devices/confirm"
  step '输入终端8位码 → 核对设备 → 核对本机名称、平台、设备标识 → 批准连接。'
  step '若提示替换已有设备，先确认确为本机，再明确勾选替换；拿不准就停下。'
  confirm '浏览器已核对并批准本设备？' || return 1
  "$collector" authorize --wait --state-dir "$TOKEN_STATE"
  status_json=$("$collector" status --state-dir "$TOKEN_STATE")
  printf '%s\n' "$status_json"
  printf '%s' "$status_json" | node --input-type=module -e 'let s=""; for await (const c of process.stdin) s+=c; if (JSON.parse(s).authorized !== true) { console.error("AUTHORIZATION_NOT_CLAIMED"); process.exitCode=1 }'

  stage '手动离线扫描'
  say '只读指定 source-home；写本机私有 SQLite 与缓存，离线模式不更新价格或上传。'
  confirm '现在扫描该来源全部历史？' || return 1
  scan_json=$("$collector" sync --offline --state-dir "$TOKEN_STATE")
  printf '%s\n' "$scan_json"
  printf '%s' "$scan_json" | node --input-type=module -e 'let s=""; for await (const c of process.stdin) s+=c; const v=JSON.parse(s); if (v.scanFailed || !(v.scan.snapshots>0)) { console.error("SCAN_NOT_READY_FOR_ACCEPTANCE"); process.exitCode=1 }'
  "$collector" status --state-dir "$TOKEN_STATE"
  say '费用 unknown/null 如实保留；Tokscale 告警只记脱敏类别，retainedDates 表示本轮没有替换的旧日期。'
  pause '记录本机结果，按 Enter 继续。'

  stage '手动线上同步'
  warn '将上传全部已扫描汇总到正式服务，并可能更新公开价格缓存。'
  say '固定 D 仅用于对账；首次在线价格更新可能改变费用和内容 hash。'
  confirm '允许现在通过正常设备凭据同步这些汇总？' || return 1
  scan_json=$("$collector" sync --state-dir "$TOKEN_STATE")
  printf '%s\n' "$scan_json"
  printf '%s' "$scan_json" | node --input-type=module -e 'let s=""; for await (const c of process.stdin) s+=c; const v=JSON.parse(s); if (v.scanFailed || !(v.scan.snapshots>0) || v.pending!==0 || v.heartbeat!==true) { console.error("ONLINE_SYNC_NOT_CONFIRMED"); process.exitCode=1 }'
  "$collector" status --state-dir "$TOKEN_STATE"
  say '须看到 pending=0、heartbeat=persisted；CLI退出成功不代替四方对账。'
  pause '记录同步结果，按 Enter 查看后续计划。'

  stage '同范围对账与定时计划'
  open_url "$server/token"
  say '选择同一个已完成北京日期 D、同一个已授权 Agent、模型 M，按设备分别与合计对账。'
  say '使用同目录 token-local-evidence.mjs 读取本地白名单快照；原始 HTTP 回执不由当前 CLI 保留。'
  say '托管 summary/usage 和页面须在获准会话分别取证；不复制请求头、不导出 HAR。'
  say '以下只展示每1小时计划，不安装任务：'
  "$collector" timer install --hours 1 --state-dir "$TOKEN_STATE"
  say '保留状态的卸载先看计划；未安装本任务就无需操作系统任务：'
  "$collector" timer uninstall --state-dir "$TOKEN_STATE"
  say '手动后续命令（在本机保留，不含凭据）：'
  printf '  %q sync --rescan --state-dir %q\n' "$collector" "$TOKEN_STATE"
  printf '  %q sync --offline --state-dir %q\n' "$collector" "$TOKEN_STATE"
  printf '  %q status --state-dir %q\n' "$collector" "$TOKEN_STATE"
  printf '  %q sources list --state-dir %q\n' "$collector" "$TOKEN_STATE"
  printf '  %q sources add --agents grok,hermes --state-dir %q\n' "$collector" "$TOKEN_STATE"
  say '长期 timer 的设备/周期/观察窗口另行安排；实际网络恢复、停用重绑及桌面手机人工仍须留证。'
  say '本向导结束仅表示手动接入步骤执行；不表示 #223/#205 整体验收通过。'
}

run_wizard "$@"; exit
